beforeExample:
public class TestClass {
    boolean instanceFlag = true;
    public void example(boolean status) {
        if (status == false) {
            System.out.println("Status is false");
        }
        boolean localFlag = instanceFlag;
        if (localFlag == false) {
            System.out.println("Local flag is false");
        }
    }
}

afterExample:
public class TestClass {
    boolean instanceFlag = true;
    public void example(boolean status) {
        if (!status) {
            System.out.println("Status is false");
        }
        boolean localFlag = instanceFlag;
        if (!localFlag) {
            System.out.println("Local flag is false");
        }
    }
}

negativeExample:
public class TestClass {
    public void example(int value) {
        // This should not match, as `value == false` is a compile error in Java.
        // The pattern `$x == false` implicitly matches only boolean-compatible expressions.
        if (value == 0) {
            System.out.println("Value is zero");
        }
    }
}
